import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();

  // --- Plane (card background) ---
  const planeGeom = new PlaneGeometry(7, 6); // size placeholder, will be scaled later if needed
  const planeMat = new MeshBasicNodeMaterial({ transparent: true });
  const plane = new Mesh(planeGeom, planeMat);
  root.add(plane);

  // Load texture (if any)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // --- Text ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 39,
      color: config.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    };
    const txtObj = ctx.fontAtlas.createText(item.text, opts);
    // Position text slightly above plane
    txtObj.position.set(0, 0, 0.01);
    root.add(txtObj);
  }

  // --- Interaction Handlers ---
  const timelines = [];

  // Hover lift (rise-in)
  const hoverEnter = () => {
    const tl = gsap.to(plane.position, { y: 0.15, duration: 0.7, ease: 'power3.out' });
    timelines.push(tl);
  };
  const hoverLeave = () => {
    const tl = gsap.to(plane.position, { y: 0, duration: 0.7, ease: 'power3.out' });
    timelines.push(tl);
  };

  // Click press-down + emit
  const onClick = () => {
    const tl = gsap.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' });
    timelines.push(tl);
    ctx.emit('hub-journal.select', {});
  };

  // Attach handlers to userData
  root.userData.handlers = {
    hover: { enter: hoverEnter, leave: hoverLeave },
    click: onClick,
  };

  // --- Cleanup ---
  root.userData.cleanup = () => {
    // Dispose material and geometry
    planeMat.dispose();
    planeGeom.dispose();
    // Dispose texture if loaded
    if (planeMat.map) planeMat.map.dispose();
    // Kill GSAP timelines
    timelines.forEach((t) => t.kill());
  };

  return root;
}
